<script>
document.getElementById('all').onchange=function(){var c=this.checked;document.querySelectorAll('.ck').forEach(function(x){x.checked=c})};
function go(a,l){var sel=[].slice.call(document.querySelectorAll('.ck:checked'));if(!sel.length){alert('Select at least one supplier');return}
var bad=sel.filter(function(x){return x.dataset.flag==='1'}).length,act=sel.filter(function(x){return x.dataset.st==='Activated'||x.dataset.st==='Password Changed'}).length,inv=sel.filter(function(x){return x.dataset.st==='Invitation Sent'}).length,fresh=sel.length-bad-act-(a==='send'?inv:0);
var m=l+'\n\nSelected: '+sel.length+'\nInvalid / missing mobile: '+bad+'\nAlready activated: '+act+'\nAlready invited: '+inv+(a==='send'||a==='resend'||a==='reset'?'\n\nNew SMS to send: about '+Math.max(0,fresh):'');
if(a==='reset'&&!confirm('Reset login for selected suppliers? Their password stops working and a new activation link is sent.'))return;
if(!confirm(m))return;document.getElementById('do').value=a;document.getElementById('sf').submit()}
</script>@endsection
